def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    adj = [[] for _ in range(N + 1)]
    index = 1
    for _ in range(N - 1):
        u = int(data[index])
        v = int(data[index + 1])
        adj[u].append(v)
        adj[v].append(u)
        index += 2

    steps = [0] * (N + 1)
    stack = [(1, -1, False)]

    while stack:
        u, parent, visited = stack.pop()
        if not visited:
            stack.append((u, parent, True))
            for v in adj[u]:
                if v != parent:
                    stack.append((v, u, False))
        else:
            sum_children = 0
            max_child = 0
            for v in adj[u]:
                if v != parent:
                    sum_children += steps[v]
                    if steps[v] > max_child:
                        max_child = steps[v]
            if u == 1:
                steps[u] = sum_children - max_child + 1
            else:
                steps[u] = sum_children + 1

    print(steps[1])

